"""A-LIN-002: held-out MQAR sequences (no download), generated by cases/A-LIN-002/harness/mqar.py with a secret seed
(ABENCH_A_LIN_SEED) on a grid of longer sequences and more key-value pairs than in training."""
from __future__ import annotations

import importlib.util
import os
import sys
from pathlib import Path

from prepare.common import Frozen

HARNESS = Path(__file__).resolve().parents[2] / "cases" / "A-LIN-002" / "harness"
SOURCES = [{"name": "MQAR (Arora et al. 2023, arXiv:2312.04927)", "generator": "cases/A-LIN-002/harness/mqar.py",
            "license": "generated by ABench"}]
GRID = [(256, 16), (512, 32), (512, 64), (1024, 64), (1024, 128), (2048, 128), (2048, 256)]
PER_CELL = 256


def _stages():
    sys.path.insert(0, str(HARNESS))
    spec = importlib.util.spec_from_file_location("a_lin_stages", HARNESS / "stages.py")
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def build(raw: Path) -> Frozen:
    seed = int(os.environ.get("ABENCH_A_LIN_SEED", "0"))
    if not seed:
        raise SystemExit("set ABENCH_A_LIN_SEED to a secret integer")
    return Frozen(public={}, hidden=_stages().build_split(seed, GRID, PER_CELL), sources_sha256={"generator": "mqar.py"})


def synthetic(n: int) -> Frozen:
    return Frozen(public={}, hidden=_stages().build_split(1, GRID[:3], max(2, n // 100)), sources_sha256={"synthetic": f"n{n}"})
